import unreal_engine as ue
from unreal_engine.classes import GameModeGeneralDataAsset

def dump_value(v, depth=0):
    if depth > 2:
        return str(v)
    t = type(v).__name__
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    if isinstance(v, list):
        return [dump_value(x, depth + 1) for x in v]
    if isinstance(v, dict):
        return {str(k): dump_value(val, depth + 1) for k, val in v.items()}
    # UE struct/object reflection best effort
    out = {'_type': t, '_str': str(v)}
    try:
        names = v.properties()
        props = {}
        for name in names:
            if name == 'NativeClass':
                continue
            try:
                props[name] = dump_value(getattr(v, name), depth + 1)
            except Exception as e:
                props[name] = 'ERR:' + str(e)
        out['props'] = props
    except Exception:
        pass
    return out

path = '/Douluo/Asset/Data/DA_GameModeGeneral.DA_GameModeGeneral'
obj = ue.load_object(GameModeGeneralDataAsset, path)
result = {'loaded': bool(obj)}
if obj:
    task_cfg = None
    for cfg in obj.ActiveGamePartConfigs:
        try:
            if getattr(cfg, 'GamePartName') == 'TaskManager':
                task_cfg = cfg
                break
        except Exception:
            pass
    result['has_task_manager'] = bool(task_cfg)
    if task_cfg:
        result['task_manager_class'] = task_cfg.get_class().get_name()
        result['TaskLineConfigList'] = dump_value(task_cfg.TaskLineConfigList)
        result['TaskConfigList'] = dump_value(task_cfg.TaskConfigList)
__askq_result = result
