import unreal_engine as ue
from unreal_engine.classes import GameModeGeneralDataAsset

path = '/Douluo/Asset/Data/DA_GameModeGeneral.DA_GameModeGeneral'
targets = {
    '每日任务': [
        (20, [(1011, 50)]),
        (40, [(1046, 100)]),
        (60, [(1022, 20)]),
        (70, [(1040, 1)]),
    ],
    '每周任务': [
        (30, [(1047, 50)]),
        (60, [(1043, 1)]),
        (90, [(1039, 5)]),
        (120, [(1044, 1)]),
    ],
}

obj = ue.load_object(GameModeGeneralDataAsset, path)
if not obj:
    raise Exception('Failed to load ' + path)

task_cfg = None
for cfg in obj.ActiveGamePartConfigs:
    if getattr(cfg, 'GamePartName', '') == 'TaskManager':
        task_cfg = cfg
        break
if not task_cfg:
    raise Exception('TaskManager config not found')

percent_template = None
award_template = None
for line in task_cfg.TaskLineConfigList:
    if percent_template is None and len(line.PercentAwardList) > 0:
        percent_template = line.PercentAwardList[0]
    for pa in line.PercentAwardList:
        if award_template is None and len(pa.ItemList) > 0:
            award_template = pa.ItemList[0]
if award_template is None:
    for task in task_cfg.TaskConfigList:
        if len(task.TaskAwardList) > 0:
            award_template = task.TaskAwardList[0]
            break
if percent_template is None:
    raise Exception('No existing FUGCPercentTaskAward struct found to clone')
if award_template is None:
    raise Exception('No existing FUGCRankingListAwardItem struct found to clone')

new_lines = []
changed = []
for line in task_cfg.TaskLineConfigList:
    new_line = line.clone()
    name = line.TaskLineName
    if name in targets:
        new_percent_awards = []
        for percent, items in targets[name]:
            pa = percent_template.clone()
            pa.set_field('Percent', percent)
            item_list = []
            for item_id, item_num in items:
                item = award_template.clone()
                item.set_field('ItemID', item_id)
                item.set_field('ItemNum', item_num)
                item_list.append(item)
            pa.set_field('ItemList', item_list)
            new_percent_awards.append(pa)
        new_line.set_field('PercentAwardList', new_percent_awards)
        changed.append(name)
    new_lines.append(new_line)

task_cfg.TaskLineConfigList = new_lines
obj.save_package()

obj2 = ue.load_object(GameModeGeneralDataAsset, path)
verify = {}
for cfg in obj2.ActiveGamePartConfigs:
    if getattr(cfg, 'GamePartName', '') == 'TaskManager':
        for line in cfg.TaskLineConfigList:
            if line.TaskLineName in targets:
                verify[line.TaskLineName] = [
                    {'Percent': pa.Percent, 'ItemList': [x.as_dict() for x in pa.ItemList]}
                    for pa in line.PercentAwardList
                ]
        break
__askq_result = {'changed_lines': changed, 'verify': verify}
